import { Interactive, Sequence, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface FogRiseProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  stagger?: number;
  blur?: number;
  tilt?: number;
  depth?: number;
  lift?: number;
  drift?: number;
  exitAt?: number;
  exitAccel?: number;
  mass?: number;
  stiffness?: number;
  damping?: number;
  spreadGap?: number;
  tracking?: number;
  resolveFrames?: number;
  fadeFrames?: number;
  speed?: number;
  className?: string;
}

function fogRiseLength(
  text: string,
  stagger = 5,
  resolveFrames = 22,
): number {
  const chars = Array.from(text);
  if (chars.length === 0) return 0;
  const center = (chars.length - 1) / 2;
  const maxRing = Math.floor(center);
  return maxRing * stagger + resolveFrames;
}

function FogRiseBase({
  text,
  fontSize = 304,
  color = "#004CFF",
  fontWeight = 400,
  stagger = 5,
  blur = 0.17,
  tilt = 55,
  depth = 5,
  lift = 0.85,
  drift = 0.005,
  exitAt = 60,
  exitAccel = 0.04,
  mass = 1.3,
  stiffness = 60,
  damping = 13,
  spreadGap = 0.07,
  tracking = -0.07,
  resolveFrames = 22,
  fadeFrames = 18,
  speed = 1,
  className,
}: FogRiseProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const chars = Array.from(text);
  const center = (chars.length - 1) / 2;
  const minRing = chars.length % 2 === 0 ? 0.5 : 0;
  const maxRing = Math.floor(center);

  const converge = spring({
    frame,
    fps,
    config: { mass, stiffness, damping },
  });
  const angle = tilt * (1 - converge);
  const liftY = lift * fontSize * (1 - converge);
  const driftY = drift * fontSize * frame;
  const exitT = exitAt > 0 ? Math.max(frame - exitAt, 0) : 0;
  const exitY = 0.5 * exitAccel * exitT * exitT * fontSize;
  const gap = spreadGap * fontSize * (1 - converge);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "flex-end",
        justifyContent: "center",
        paddingBottom: "6%",
        whiteSpace: "nowrap",
        perspective: `${depth * fontSize}px`,
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          transform: `translateY(${liftY - driftY - exitY}px) rotateX(${-angle}deg)`,
          transformOrigin: "50% 100%",
          fontSize,
          fontWeight,
          color,
          letterSpacing: `${tracking}em`,
          lineHeight: 1.15,
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
        }}
      >
        {chars.map((char, j) => {
          const ring = Math.abs(j - center) - minRing;
          const startAt = ring * stagger;

          const opacity = interpolate(
            frame,
            [startAt, startAt + fadeFrames],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
          );

          const charBlur =
            blur *
            fontSize *
            interpolate(frame, [0, maxRing * stagger + resolveFrames], [1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

          return (
            <span
              key={j}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                marginRight: j < chars.length - 1 ? gap : undefined,
                opacity,
                filter: charBlur > 0.05 ? `blur(${charBlur}px)` : undefined,
              }}
            >
              {char}
            </span>
          );
        })}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Remocn",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 40,
    max: 560,
    step: 4,
    default: 304,
    description: "Font size",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    min: 0,
    max: 15,
    step: 1,
    default: 5,
    description: "Frames / ring",
    hiddenFromList: false,
  },
  blur: {
    type: "number",
    min: 0,
    max: 0.5,
    step: 0.01,
    default: 0.17,
    description: "Blur (em)",
    hiddenFromList: false,
  },
  tilt: {
    type: "number",
    min: 0,
    max: 90,
    step: 5,
    default: 55,
    description: "Start tilt (deg)",
    hiddenFromList: false,
  },
  depth: {
    type: "number",
    min: 1,
    max: 8,
    step: 0.5,
    default: 5,
    description: "Perspective depth",
    hiddenFromList: false,
  },
  lift: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.85,
    description: "Lift (em)",
    hiddenFromList: false,
  },
  drift: {
    type: "number",
    min: 0,
    max: 0.012,
    step: 0.001,
    default: 0.005,
    description: "Drift (em / frame)",
    hiddenFromList: false,
  },
  exitAt: {
    type: "number",
    min: 0,
    max: 200,
    step: 5,
    default: 60,
    description: "Exit frame",
    hiddenFromList: false,
  },
  exitAccel: {
    type: "number",
    min: 0.002,
    max: 0.05,
    step: 0.002,
    default: 0.04,
    description: "Exit accel",
    hiddenFromList: false,
  },
  mass: {
    type: "number",
    min: 0.3,
    max: 3,
    step: 0.1,
    default: 1.3,
    description: "Mass",
    hiddenFromList: false,
  },
  stiffness: {
    type: "number",
    min: 30,
    max: 250,
    step: 10,
    default: 60,
    description: "Stiffness",
    hiddenFromList: false,
  },
  damping: {
    type: "number",
    min: 5,
    max: 30,
    step: 1,
    default: 13,
    description: "Damping",
    hiddenFromList: false,
  },
  spreadGap: {
    type: "number",
    min: 0,
    max: 0.3,
    step: 0.01,
    default: 0.07,
    description: "Spread gap (em)",
    hiddenFromList: false,
  },
  tracking: {
    type: "number",
    min: -0.12,
    max: 0,
    step: 0.005,
    default: -0.07,
    description: "Tracking (em)",
    hiddenFromList: false,
  },
  resolveFrames: {
    type: "number",
    min: 8,
    max: 50,
    step: 1,
    default: 22,
    description: "Converge frames",
    hiddenFromList: false,
  },
  fadeFrames: {
    type: "number",
    min: 2,
    max: 25,
    step: 1,
    default: 18,
    description: "Fade frames",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#004CFF",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "400",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","stagger","blur","tilt","depth","lift","drift","exitAt","exitAccel","mass","stiffness","damping","spreadGap","tracking","resolveFrames","fadeFrames","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Remocn",
  fontSize: 304,
  stagger: 5,
  blur: 0.17,
  tilt: 55,
  depth: 5,
  lift: 0.85,
  drift: 0.005,
  exitAt: 60,
  exitAccel: 0.04,
  mass: 1.3,
  stiffness: 60,
  damping: 13,
  spreadGap: 0.07,
  tracking: -0.07,
  resolveFrames: 22,
  fadeFrames: 18,
  color: "#004CFF",
  fontWeight: "400",
  speed: 1,
};

type FogRiseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FogRiseBase>;

const FogRiseInner = forwardRef<
  HTMLDivElement,
  FogRiseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FogRise>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FogRiseBase
          {...(componentProps as unknown as ComponentProps<typeof FogRiseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FogRise = Interactive.withSchema({
  Component: FogRiseInner,
  componentName: "<FogRise>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
